func TestFailureSeqIsStrictlyIncreasingAndNeverReused(t *testing.T) {
	r := New()
	failItem(r, KindScan, "ctx", "/w/a", "x")
	failItem(r, KindScan, "ctx", "/w/b", "x")
	fs := r.Failures()
